wrong_polygon_nominal_bounds.replace:
      match paint_points_bounds(points) {
        None => None
        Some(bounds) => @primitives.Rect::new(bounds.left(), bounds.top() - 30.0, bounds.size().width(), bounds.size().height() + 30.0).to_option()
      }
    }
  }
